CREATE TABLE feed_posts(post_id UUID PRIMARY KEY,author_id VARCHAR(120) NOT NULL,caption TEXT,visibility VARCHAR(20) NOT NULL,status VARCHAR(20) NOT NULL,catalog_asset_id UUID,media_ids TEXT NOT NULL,hashtags TEXT NOT NULL,available BOOLEAN NOT NULL,published_at TIMESTAMPTZ,updated_at TIMESTAMPTZ NOT NULL,version BIGINT NOT NULL DEFAULT 0);
CREATE INDEX idx_feed_posts_available ON feed_posts(published_at DESC) WHERE available=true;CREATE INDEX idx_feed_posts_author ON feed_posts(author_id,published_at DESC);
CREATE TABLE feed_post_metrics(post_id UUID PRIMARY KEY,likes BIGINT NOT NULL DEFAULT 0,comments BIGINT NOT NULL DEFAULT 0,shares BIGINT NOT NULL DEFAULT 0,favorites BIGINT NOT NULL DEFAULT 0,updated_at TIMESTAMPTZ NOT NULL,version BIGINT NOT NULL DEFAULT 0,CONSTRAINT ck_feed_metrics_nonnegative CHECK(likes>=0 AND comments>=0 AND shares>=0 AND favorites>=0));
CREATE TABLE feed_user_post_signals(id UUID PRIMARY KEY,user_id VARCHAR(120) NOT NULL,post_id UUID NOT NULL,weight DOUBLE PRECISION NOT NULL,updated_at TIMESTAMPTZ NOT NULL,version BIGINT NOT NULL DEFAULT 0,CONSTRAINT uk_feed_signal_user_post UNIQUE(user_id,post_id),CONSTRAINT ck_feed_signal_weight CHECK(weight>=0));CREATE INDEX idx_feed_signals_user ON feed_user_post_signals(user_id);
CREATE TABLE feed_processed_events(event_id UUID PRIMARY KEY,event_type VARCHAR(120) NOT NULL,processed_at TIMESTAMPTZ NOT NULL);
CREATE TABLE feed_outbox(id UUID PRIMARY KEY,aggregate_id VARCHAR(120) NOT NULL,event_type VARCHAR(120) NOT NULL,payload TEXT NOT NULL,occurred_at TIMESTAMPTZ NOT NULL,published_at TIMESTAMPTZ,attempts INTEGER NOT NULL DEFAULT 0,last_error VARCHAR(1000));CREATE INDEX idx_feed_outbox_pending ON feed_outbox(occurred_at) WHERE published_at IS NULL;
